class Solution:
    def maxPartitionFactor(self, points: List[List[int]]) -> int:
        n = len(points)
        if n == 2:
            return 0
        ds = sorted({abs(a[0] - b[0]) + abs(a[1] - b[1])
                     for i, a in enumerate(points) for b in points[i + 1:]})

        def ok(d):
            g = [[] for _ in range(n)]
            for i in range(n):
                xi, yi = points[i]
                for j in range(i + 1, n):
                    if abs(xi - points[j][0]) + abs(yi - points[j][1]) < d:
                        g[i].append(j)
                        g[j].append(i)
            col = [-1] * n
            for s in range(n):
                if col[s] == -1:
                    col[s] = 0
                    st = [s]
                    while st:
                        u = st.pop()
                        for v in g[u]:
                            if col[v] == -1:
                                col[v] = col[u] ^ 1
                                st.append(v)
                            elif col[v] == col[u]:
                                return False
            return True

        lo, hi, ans = 0, len(ds) - 1, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if ok(ds[mid]):
                ans = ds[mid]
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

