class Solution {
public:
    int maxPartitionFactor(vector<vector<int>>& points) {
        int n = points.size();
        if (n == 2) return 0;
        vector<long long> ds;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                ds.push_back((long long)abs(points[i][0]-points[j][0]) + abs(points[i][1]-points[j][1]));
        sort(ds.begin(), ds.end());
        ds.erase(unique(ds.begin(), ds.end()), ds.end());
        auto ok = [&](long long d) {
            vector<vector<int>> g(n);
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    long long dd = (long long)abs(points[i][0]-points[j][0]) + abs(points[i][1]-points[j][1]);
                    if (dd < d) { g[i].push_back(j); g[j].push_back(i); }
                }
            vector<int> col(n, -1);
            for (int s = 0; s < n; s++)
                if (col[s] < 0) {
                    col[s] = 0;
                    vector<int> st{s};
                    while (!st.empty()) {
                        int u = st.back(); st.pop_back();
                        for (int v : g[u]) {
                            if (col[v] < 0) { col[v] = col[u] ^ 1; st.push_back(v); }
                            else if (col[v] == col[u]) return false;
                        }
                    }
                }
            return true;
        };
        int lo = 0, hi = ds.size() - 1, ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ok(ds[mid])) { ans = ds[mid]; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }
};

