class Solution {
    public int maxPartitionFactor(int[][] points) {
        int n = points.length;
        if (n == 2) return 0;
        TreeSet<Long> set = new TreeSet<>();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                set.add((long)Math.abs(points[i][0]-points[j][0]) + Math.abs(points[i][1]-points[j][1]));
        List<Long> ds = new ArrayList<>(set);
        int lo = 0, hi = ds.size() - 1, ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ok(points, ds.get(mid))) { ans = ds.get(mid).intValue(); lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }

    private boolean ok(int[][] pts, long d) {
        int n = pts.length;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                long dd = (long)Math.abs(pts[i][0]-pts[j][0]) + Math.abs(pts[i][1]-pts[j][1]);
                if (dd < d) { g.get(i).add(j); g.get(j).add(i); }
            }
        int[] col = new int[n];
        Arrays.fill(col, -1);
        for (int s = 0; s < n; s++)
            if (col[s] < 0) {
                col[s] = 0;
                Deque<Integer> st = new ArrayDeque<>();
                st.push(s);
                while (!st.isEmpty()) {
                    int u = st.pop();
                    for (int v : g.get(u)) {
                        if (col[v] < 0) { col[v] = col[u] ^ 1; st.push(v); }
                        else if (col[v] == col[u]) return false;
                    }
                }
            }
        return true;
    }
}

