class Solution {
    private int[] p, par;

    private int[] find(int x) {
        if (p[x] == x) return new int[]{x, 0};
        int[] r = find(p[x]);
        p[x] = r[0];
        par[x] ^= r[1];
        return new int[]{r[0], par[x]};
    }

    public int maxPartitionFactor(int[][] points) {
        int n = points.length;
        if (n == 2) return 0;
        TreeSet<Long> set = new TreeSet<>();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                set.add((long)Math.abs(points[i][0]-points[j][0]) + Math.abs(points[i][1]-points[j][1]));
        List<Long> ds = new ArrayList<>(set);
        int lo = 0, hi = ds.size() - 1, ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ok(points, ds.get(mid))) { ans = ds.get(mid).intValue(); lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }

    private boolean ok(int[][] pts, long d) {
        int n = pts.length;
        p = new int[n]; par = new int[n];
        for (int i = 0; i < n; i++) p[i] = i;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                long dd = (long)Math.abs(pts[i][0]-pts[j][0]) + Math.abs(pts[i][1]-pts[j][1]);
                if (dd < d) {
                    int[] a = find(i), b = find(j);
                    if (a[0] == b[0]) { if (a[1] == b[1]) return false; }
                    else { p[a[0]] = b[0]; par[a[0]] = a[1] ^ b[1] ^ 1; }
                }
            }
        return true;
    }
}

